<!doctype html><html lang="en"><head><meta charset="UTF-8"><title>Recruiter Analytics</title><link rel="stylesheet" href="/project/public/assets/css/style.css"></head><body><div class="container"><h2>Recruiter Analytics</h2><div class="table-wrap"><table><tr><th>Metric</th><th>Value</th></tr><tr><td>Total outreach sent</td><td><?php echo (int)$summary['total_outreach']; ?></td></tr><tr><td>Outreach response rate</td><td><?php echo (float)$summary['response_rate']; ?>%</td></tr><tr><td>Total applications managed</td><td><?php echo (int)$summary['total_applications_managed']; ?></td></tr><tr><td>Placement success rate</td><td><?php echo (float)$summary['placement_success_rate']; ?>%</td></tr></table></div><h3>Client Report</h3><form method="get" action="index.php"><input type="hidden" name="route" value="recruiter/analytics"><label>Select Client</label><select name="employer_id"><option value="">All Clients</option><?php foreach ($clients as $client): if (!$client['employer_id']) continue; ?><option value="<?php echo (int)$client['employer_id']; ?>" <?php echo (string)$client['employer_id'] === (string)($_GET['employer_id'] ?? '') ? 'selected' : ''; ?>><?php echo htmlspecialchars($client['employer_company_name'] ?? $client['employer_owner_name']); ?></option><?php endforeach; ?></select><div class="actions"><button type="submit">Generate</button><a class="btn btn-secondary" href="index.php?route=recruiter/dashboard">Back</a></div></form><div class="table-wrap"><table><tr><th>Client</th><th>Total Jobs</th><th>Total Applications</th><th>Submitted</th><th>Reviewed</th><th>Shortlisted</th><th>Interview</th><th>Hired</th></tr><?php foreach ($clientReport as $row): ?><tr><td><?php echo htmlspecialchars($row['client_name']); ?></td><td><?php echo (int)$row['total_jobs']; ?></td><td><?php echo (int)$row['total_applications']; ?></td><td><?php echo (int)$row['submitted']; ?></td><td><?php echo (int)$row['reviewed']; ?></td><td><?php echo (int)$row['shortlisted']; ?></td><td><?php echo (int)$row['interview']; ?></td><td><?php echo (int)$row['hired']; ?></td></tr><?php endforeach; ?></table></div></div></body></html>
